INSERT INTO _lab_req_stage (credential_type, slug, lab_key, why) VALUES
  ('certificate', 'cert-adr-and-voice-recording-v3', 'tr_speech', 'ADR is judged on whether the replaced line still sounds like speech, so you need to know how the voice makes its sounds.'),
  ('certificate', 'cert-adr-and-voice-recording-v3', 'tr_smart_processors', 'Close-miked replacement dialogue often needs de-essing before anyone will accept it.'),
  ('certificate', 'cert-adr-and-voice-recording-v3', 'mk_B07', 'Voiceover and narration are recorded close and controlled, and a guest’s return feed must never contain their own voice.'),
  ('certificate', 'cert-adr-and-voice-recording-v3', 'mk_F09', 'Location speech is a boom just outside the frame and a body microphone, each on its own channel — the material everyone after you works from.'),
  ('certificate', 'cert-ai-voice-and-speech-synthesis-v3', 'tr_speech', 'You cannot judge synthetic speech without knowing how real voicing, vowels and formants behave.'),
  ('certificate', 'cert-amplifier-technology-v3', 'tr_amp', 'Amplifier classes, the load the amp sees and where the power comes from are the subject of this certificate.'),
  ('certificate', 'cert-analog-console-recording-v3', 'mxb_terms', 'Inserts, sends, returns, buses, groups and auxes are the six words every routing conversation uses.'),
  ('certificate', 'cert-analog-console-recording-v3', 'mxb_sends', 'Pre- and post-fader sends decide whether an effect follows the fader — and when a route accidentally doubles.'),
  ('certificate', 'cert-analog-electronics-for-audio-v3', 'tr_amp', 'Transistors, transformers and amplifier topologies are where these components actually get used.'),
  ('certificate', 'cert-assisted-listening-and-accessibility-v3', 'tr_speech', 'Assisted listening is measured in speech intelligibility, which starts with how speech is produced and heard.'),
  ('certificate', 'cert-audio-archival-and-restoration-v3', 'tr_eq', 'Restoration is mostly filtering, and knowing when a filter is removing the recording along with the noise.'),
  ('certificate', 'cert-audio-archival-and-restoration-v3', 'ear_defect', 'Hum, hiss, crackle, clicks and dropouts have to be named by ear before they can be removed.'),
  ('certificate', 'cert-audio-career-and-business-v3', 'tr_preprod', 'Scoping a job and costing it out — people, schedule, budget — is the business side of audio in practice.'),
  ('certificate', 'cert-audio-measurement-and-analysis-v3', 'mk_F11', 'A measurement is only as good as its microphone and its calibration, checked before and after.'),
  ('certificate', 'cert-audio-measurement-and-analysis-v3', 'mk_F13', 'Room acoustics are measured from seats that differ, with the reverberation figures kept apart from each other.'),
  ('certificate', 'cert-audio-measurement-and-analysis-v3', 'mk_F14', 'Loudspeaker and system measurement depends on naming the measurement point and the delay before trusting any reading.'),
  ('certificate', 'cert-audio-troubleshooting-specialist-v3', 'tr_amp', 'Fault-finding inside analog gear means knowing what the circuit was supposed to be doing.'),
  ('certificate', 'cert-audio-troubleshooting-specialist-v3', 'ear_defect', 'Troubleshooting starts by naming the symptom by ear — hum, buzz, crackle or dropout each point somewhere different.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'tr_mic_select', 'Tracking a band is a run of microphone choices, each one defensible for its source.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'tr_phase', 'A band in one room means many microphones hearing the same sources, and phase decides whether they add up.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'tr_drum_tuning', 'The kit sound is decided at the drums before any microphone goes up.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_M01', 'The kick is the foundation of a recorded kit, and where its microphone sits decides how much punch and how much boom you get.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_M02', 'The snare sits right beside the hi-hat, so placing its microphone is a balance between the drum and what leaks in.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_M03', 'Toms ring under the cymbals, and their microphones have to catch the drum without filling up with crash.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_M09', 'In many mixes, the overheads are the picture of the whole kit that the close microphones are added to.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_M10', 'Room microphones decide how big the kit sounds, and how much of the room comes with it.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_M11', 'A full kit is a plan — how many microphones, where the bleed goes, and whether it all holds up in mono.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_I01a', 'The hi-hat leaks into the snare microphone, so its own microphone is placed with that in mind.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_I01b', 'The ride carries the time on many songs and can vanish or swamp the overheads depending on placement.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_I01c', 'Crashes are caught first by the overheads; knowing when one needs its own microphone keeps a kit from getting crowded.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_I01d', 'A splash is a short accent among loud neighbours, and it is easy either to lose or to over-mic.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_I01e', 'A china is harsh and loud, and where its microphone sits decides whether it cuts through or hurts.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_C01', 'Acoustic guitar is one of the most-recorded sources there is, and small moves along the body change it completely.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_C02', 'Most electric guitar on a record is the amplifier’s speaker as the microphone hears it.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_C08', 'Electric bass is usually captured with a microphone and a direct signal together, and the two have to agree.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_SPK', 'Guitar and bass cabinets and the rotating speaker cabinet are miked from outside, with rules of their own.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_C11', 'Piano is a large source with many workable answers, and the lid, the strings and the soundboard all change what you get.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_E01', 'The lead vocal is the most important microphone in most sessions and shows, and distance from the lips decides its sound.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_E02', 'Background and harmony vocals are balanced by distance and spacing, and the wrong spacing turns them into phase trouble.'),
  ('certificate', 'cert-band-tracking-specialist-v3', 'mk_E09', 'A band starts as a stage plot — the fewest microphones that do the job, with every open microphone counted.'),
  ('certificate', 'cert-bioacoustics-and-ecoacoustics-v3', 'mk_F06', 'Ambience is chosen by ear at a listening point off every path, protected from wind and checked in mono.'),
  ('certificate', 'cert-bioacoustics-and-ecoacoustics-v3', 'mk_F07', 'Wildlife and distant sources are recorded from a permitted point, with the microphone aimed at the call rather than the noise.'),
  ('certificate', 'cert-broadcast-engineer-v3', 'tr_compression', 'The air chain is built around compression and limiting — threshold, ratio and release shape how the station sounds.'),
  ('certificate', 'cert-broadcast-engineer-v3', 'tr_limiter', 'Broadcast is delivered to a hard ceiling and a loudness target.'),
  ('certificate', 'cert-broadcast-engineer-v3', 'mk_B01', 'Hosts on a desk microphone, each on their own channel, are the heart of most radio and podcast studios.'),
  ('certificate', 'cert-car-audio-installation-v3', 'tr_amp', 'Matching amplifiers to speaker loads without damaging either is the core of a vehicle install.'),
  ('certificate', 'cert-compression-and-dynamics-v3', 'tr_compression', 'This certificate is compression — threshold, ratio, attack, release and the envelope they produce.'),
  ('certificate', 'cert-compression-and-dynamics-v3', 'tr_gate', 'Gating and downward expansion are the other half of dynamics control.'),
  ('certificate', 'cert-compression-and-dynamics-v3', 'tr_limiter', 'Limiting, true-peak and loudness are where a dynamics chain ends up.'),
  ('certificate', 'cert-compression-and-dynamics-v3', 'ear_compression', 'You have to hear compression — the envelope changing, not just the level — to set it well.'),
  ('certificate', 'cert-compression-and-dynamics-v3', 'mxa_parallel', 'Parallel and multibus processing adds weight and control without crushing the original.'),
  ('certificate', 'cert-compression-and-dynamics-v3', 'mxa_adv_dyn', 'Advanced dynamics — sidechains, multiband and ducking — solve problems a single compressor cannot.'),
  ('certificate', 'cert-compression-and-dynamics-v3', 'mxa_bus', 'Mix-bus processing changes everything at once, so it has to be done on purpose.'),
  ('certificate', 'cert-corporate-and-event-production-v3', 'tr_preprod', 'An event lives or dies on the scope, crew and schedule agreed before load-in.'),
  ('certificate', 'cert-corporate-and-event-production-v3', 'tr_sound_systems', 'Designing, wiring and tuning the event’s system is one of this certificate’s named topics.'),
  ('certificate', 'cert-corporate-and-event-production-v3', 'mk_B05', 'Lavaliers and headsets are fitted, hidden and positioned on the wearer, and a few centimetres change the voice completely.'),
  ('certificate', 'cert-corporate-and-event-production-v3', 'mk_B06', 'Panels, lecterns and press conferences need every voice heard with the fewest open microphones.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'ear_frequency', 'Naming a frequency by ear is the bedrock of every tonal descriptor.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'ear_eq', 'Hearing one EQ move — where, which way and how much — is what tonal description is for.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'ear_band', 'The named bands are the vocabulary this certificate is tested in.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'ear_noise', 'Noise colours and basic waveforms are the reference timbres everything else is described against.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'ear_defect', 'Artifact identification is one of this certificate’s named topics.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'ear_clipping', 'Clipping is the artifact most often missed until it is too late.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'ear_comb', 'Comb filtering is the hollow, phasey artifact you will be asked to name and explain.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'ear_compression', 'Over-compression is an artifact of the envelope, and you have to hear it to call it.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'tr_envelope', 'Attack, decay and resonance are the descriptors this certificate is tested on.'),
  ('certificate', 'cert-critical-listening-and-ear-training-v3', 'tr_speech', 'Voice is the source you will be asked to describe most often.'),
  ('certificate', 'cert-daw-power-user-v3', 'mxb_prep', 'A prepared session is named, cleaned, phase-checked and saved before a single decision is made.'),
